import {OUTLOOK_TEXT} from './narrative-outlook-content.js';
import {seatAt} from './narrative-character-history.js';
export {seatAt,conditionAt} from './narrative-character-history.js';
import {originOrder,FAMILY_POLICY,CLAIM_BASES} from './narrative-family.js';
const fail=m=>{throw Error('Invalid succession/regency: '+m);};
const ordered=v=>Array.isArray(v)?v.map(ordered):v&&typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,ordered(v[k])])):v;
export const equalData=(a,b)=>JSON.stringify(ordered(a))===JSON.stringify(ordered(b));
export const politicalKind=s=>s.control==='company'?'company-dependent-ruler':s.overlord?'vassal-ruler':'sovereign-ruler';
export const positionFor=kind=>({'sovereign-ruler':'sovereign ruler','vassal-ruler':'subordinate ruler','company-dependent-ruler':'retained local ruler'}[kind]);
export const activeRegency=(s,region)=>(s.narrative?.regencies||[]).find(r=>r.region===region&&!r.end);
export const recordedRuler=(s,id)=>(s.narrative?.successionRecords||[]).some(r=>r.successorId===id);

export function successionOrigins(s){return [...(s.narrative?.successionRecords||[]).flatMap(r=>[{label:'Succession '+r.id,origin:r.origin},...(r.evidence||[]).filter(e=>e.origin).map(e=>({label:'Succession eligibility '+r.id,origin:e.origin}))]),...(s.narrative?.regencies||[]).flatMap(r=>[{label:'Regency '+r.id,origin:r.start},...(r.end?[{label:'Regency ending '+r.id,origin:r.end}]:[])])];}
export function successionPolicy(input={}){
 const keys=['adultAge','allowMinors','allowDormant','standings','bases','basisPriority','regentBases','appointments'];if(Object.keys(input).some(k=>!keys.includes(k)))fail('unknown narrative policy');
 const p={adultAge:18,allowMinors:true,allowDormant:false,standings:['recognised'],bases:[...CLAIM_BASES],basisPriority:[],regentBases:['guardian'],appointments:[],...JSON.parse(JSON.stringify(input))};
 if(!Number.isInteger(p.adultAge)||p.adultAge<18||p.adultAge>100||typeof p.allowMinors!=='boolean'||typeof p.allowDormant!=='boolean'||!Array.isArray(p.standings)||p.standings.some(x=>!['recognised','contested','unrecognised'].includes(x))||!Array.isArray(p.bases)||p.bases.some(x=>!CLAIM_BASES.includes(x))||!Array.isArray(p.basisPriority)||p.basisPriority.some(x=>!CLAIM_BASES.includes(x))||!Array.isArray(p.regentBases)||p.regentBases.some(x=>!['guardian','parent','adoptive-parent'].includes(x))||!Array.isArray(p.appointments)||p.appointments.length>100)fail('narrative policy');for(const key of ['standings','bases','basisPriority','regentBases'])if(new Set(p[key]).size!==p[key].length)fail('duplicate policy entry');const appointments=new Set(),targets=new Set();for(const a of p.appointments){if(!a||typeof a.id!=='string'||!a.id||typeof a.characterId!=='string'||a.kind!=='court-appointment'||appointments.has(a.id)||targets.has(a.characterId+':'+a.region))fail('appointment policy');appointments.add(a.id);targets.add(a.characterId+':'+a.region);}return p;
}
export function validateSuccessionState(s){
 const n=s.narrative,records=n.successionRecords||[],regencies=n.regencies||[];
 if(n.successionRecords!==undefined&&!Array.isArray(n.successionRecords)||n.regencies!==undefined&&!Array.isArray(n.regencies)||records.length>1000||regencies.length>1000)fail('bounded collections');
 const ids=new Set(),lastByRegion=new Map();let order=-1;
 const hasRole=(c,from,to,o)=>c.politicalHistory?.some(t=>t.from.kind===from&&t.to.kind===to&&t.source.incidentId===o.source.incidentId);
 for(const r of records){
  if(!r||typeof r.id!=='string'||ids.has(r.id)||r.testOnly!==true||!n.characters[r.incumbentId]||!n.characters[r.successorId]||r.incumbentId===r.successorId||!['abdication','confirmed-death'].includes(r.exit))fail('record identity/exit');ids.add(r.id);
  const index=originOrder(s,r.origin),h=s.history[index],fact=h?.incident?.facts.find(f=>f.type==='synthetic-succession');if(index<=order||h.actionType!=='test-succession'||h.incident.provenance!=='manual-test'||h.input?.manualTest!==true||h.incident.input.manualTest!==true||h.input.testId!==r.id||!fact||fact.recordId!==r.id||fact.region!==r.region||fact.incumbentId!==r.incumbentId||fact.successorId!==r.successorId||fact.exit!==r.exit||fact.claimId!==r.claimId||fact.regentId!==r.regentId||fact.successorAgeAtStart!==r.successorAgeAtStart||fact.regentAgeAtStart!==r.regentAgeAtStart||!equalData(fact.boardBefore,r.boardBefore))fail('canonical succession source');order=index;
  if(h.incident.changes.length||!r.boardBefore||politicalKind(r.boardBefore)!==r.politicalKind||JSON.stringify(h.incident.laws.before)!==JSON.stringify(h.incident.laws.after)||JSON.stringify(h.incident.elephant.before)!==JSON.stringify(h.incident.elephant.after))fail('board boundary');
  if(!Number.isInteger(r.successorAgeAtStart)||r.successorAgeAtStart<0||r.successorAgeAtStart>n.characters[r.successorId].age||r.successorAgeAtStart<r.policy.adultAge&&!r.regentId||r.successorAgeAtStart>=r.policy.adultAge&&r.regentId||['army','secretary'].includes(n.characters[r.successorId].role))fail('titular eligibility/start age');
  if(n.characters[r.successorId].region!==r.region||n.characters[r.incumbentId].region!==r.region||!hasRole(n.characters[r.incumbentId],r.politicalKind,'former-ruler',r.origin)||!hasRole(n.characters[r.successorId],r.successorPriorRole.kind,r.politicalKind,r.origin))fail('persona/role evidence');
  const prior=lastByRegion.get(r.region);if(prior&&prior.successorId!==r.incumbentId)fail('seat chain');lastByRegion.set(r.region,r);
  const claim=(n.claimsV2||[]).find(c=>c.id===r.claimId);if(!claim||claim.claimantId!==r.successorId||claim.region!==r.region||!(claim.origin.source.incidentId===r.origin.source.incidentId&&claim.status==='realised')&&!claim.statusHistory?.some(t=>t.to==='realised'&&t.origin.source.incidentId===r.origin.source.incidentId))fail('claim realisation');
  if(r.exit==='confirmed-death'&&!n.characters[r.incumbentId].conditionHistory?.some(t=>t.from==='alive'&&t.to==='dead'&&t.source.incidentId===r.origin.source.incidentId))fail('confirmed-death evidence');
  if(!equalData(r.request,h.input.request)||!equalData(r.request,h.incident.input.request)||!equalData(r.policy,successionPolicy(r.request.policy))||r.request.region!==r.region||r.request.incumbentId!==r.incumbentId||r.request.exit!==r.exit||r.request.choice&&(r.request.choice.characterId!==r.successorId||r.request.choice.claimId!==undefined&&r.request.choice.claimId!==null&&r.request.choice.claimId!==r.claimId||r.request.choice.regentId&&r.request.choice.regentId!==r.regentId))fail('request/decision mismatch');
  if(!Array.isArray(r.evidence)||r.evidence.length>100||!r.policy||!r.request||r.request.id!==r.id)fail('saved decision');for(const e of r.evidence){if(!['claim','family-link','court-appointment','regional-state'].includes(e.kind))fail('selection evidence kind');if(e.kind==='claim'){const c=(n.claimsV2||[]).find(c=>c.id===e.id);if(e.id!==r.claimId||!equalData(e.origin,c?.origin))fail('claim evidence identity');}if(e.kind==='family-link'){const l=(n.familyLinks||[]).find(l=>l.id===e.id);if(!l||!equalData(l.origin,e.origin)||![l.fromId,l.toId].includes(r.successorId))fail('family selection evidence');}if(e.kind==='regional-state'&&(e.region!==r.region||e.politicalKind!==r.politicalKind||e.control!==r.boardBefore.control||e.overlord!==r.boardBefore.overlord))fail('regional selection evidence');if(e.kind==='court-appointment'){const a=r.policy.appointments.find(a=>a.id===e.id&&a.characterId===r.successorId&&a.region===r.region);if(!a||!equalData(a.origin,e.origin)||r.politicalKind==='company-dependent-ruler')fail('court appointment evidence');}if(e.origin&&originOrder(s,e.origin)>=index)fail('future selection evidence');if(e.kind==='claim'&&!(n.claimsV2||[]).some(c=>c.id===e.id)||e.kind==='family-link'&&!(n.familyLinks||[]).some(l=>l.id===e.id))fail('selection reference');}
  if(r.privateOutlookBefore&&(r.privateOutlookBefore.characterId!==r.incumbentId||r.privateOutlookBefore.visibility!=='private'||typeof r.privateOutlookBefore.text!=='string'||!Object.hasOwn(OUTLOOK_TEXT,r.privateOutlookBefore.templateId)||r.privateOutlookBefore.text!==OUTLOOK_TEXT[r.privateOutlookBefore.templateId]||!Array.isArray(r.privateOutlookBefore.memoryIds)||r.privateOutlookBefore.memoryIds.some(id=>n.memories[id]?.ownerId!==r.incumbentId)||r.privateOutlookBefore.sourceIncidentId!==null&&!s.history.slice(0,index).some(h=>h.incident?.id===r.privateOutlookBefore.sourceIncidentId)))fail('private archive owner');
 }
 for(const [region,r]of lastByRegion)if(n.seats[region]!==r.successorId||n.characters[r.successorId].politicalRole?.kind!==politicalKind(s.regions[region]))fail('current seat does not match succession chain');
 const regIds=new Set(),activeRegions=new Set(),activePeople=new Set();
 for(const t of regencies){
  if(!t||regIds.has(t.id)||!n.characters[t.regentId]||!n.characters[t.rulerId]||t.regentId===t.rulerId||!records.some(r=>r.id===t.successionId&&r.region===t.region&&r.origin.source.incidentId===t.start?.source.incidentId&&r.successorId===t.rulerId&&r.regentId===t.regentId)||!Number.isInteger(t.adultAge)||t.adultAge<FAMILY_POLICY.adultAge||!Number.isInteger(t.ageAtStart)||t.ageAtStart<0||t.ageAtStart>=t.adultAge)fail('regency identity/start');regIds.add(t.id);const record=records.find(r=>r.id===t.successionId);if(record.successorAgeAtStart!==t.ageAtStart||record.regentAgeAtStart!==t.regentAgeAtStart||t.regentAgeAtStart<t.adultAge||t.adultAge!==record.policy.adultAge)fail('regent start eligibility');originOrder(s,t.start);
  if(!hasRole(n.characters[t.regentId],t.priorRole.kind,'regent',t.start))fail('regent role start');
  if(t.end){const index=originOrder(s,t.end),h=s.history[index],f=h.incident.facts.find(f=>f.type==='synthetic-regency-end');if(index<=originOrder(s,t.start)||h.actionType!=='test-regency-end'||h.incident.provenance!=='manual-test'||h.incident.changes.length||f?.regencyId!==t.id||f.rulerId!==t.rulerId||f.regentId!==t.regentId||f.ageAtEnd!==t.ageAtEnd||t.ageAtEnd<t.adultAge||!hasRole(n.characters[t.regentId],'regent',t.priorRole.kind,t.end))fail('regency ending');}
  else{if(activeRegions.has(t.region)||activePeople.has(t.regentId)||n.seats[t.region]!==t.rulerId||Object.values(n.seats).includes(t.regentId)||n.characters[t.regentId].condition!=='alive'||n.characters[t.regentId].age<t.adultAge||['army','secretary'].includes(n.characters[t.regentId].role)||n.characters[t.regentId].politicalRole?.kind!=='regent'||n.characters[t.regentId].politicalRole.region!==t.region)fail('active regent/seat');activeRegions.add(t.region);activePeople.add(t.regentId);}
 }
 for(let i=0;i<regencies.length;i++)for(let j=i+1;j<regencies.length;j++){const a=regencies[i],b=regencies[j];if((a.region===b.region||a.regentId===b.regentId)&&Math.max(originOrder(s,a.start),originOrder(s,b.start))<Math.min(a.end?originOrder(s,a.end):Infinity,b.end?originOrder(s,b.end):Infinity))fail('overlapping regencies');}
 for(const h of s.history)for(const f of h.incident?.facts||[]){if(f.type==='synthetic-succession'&&!records.some(r=>r.id===f.recordId&&r.origin.source.incidentId===h.incident.id))fail('orphaned succession source');if(f.type==='synthetic-regency-end'&&!regencies.some(t=>t.id===f.regencyId&&t.end?.source.incidentId===h.incident.id))fail('orphaned regency ending');}
 for(const r of records)if(r.regentId&&!regencies.some(t=>t.successionId===r.id))fail('missing regency');
}


export const speakerRoleAt=(s,c,entry)=>c?(seatAt(s,c.region,entry)===c.id?'ruler':c.role):undefined;
